import{_ as a,o as t,c as s,a0 as n}from"./chunks/framework.BE1i3JtZ.js";const u=JSON.parse('{"title":"App 整包升级（Android APK / iOS 跳商店 / H5 提示刷新）设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-16-app-upgrade-design.md","filePath":"superpowers/specs/2026-09-16-app-upgrade-design.md"}'),o={name:"superpowers/specs/2026-09-16-app-upgrade-design.md"};function l(d,e,i,p,c,r){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="app-整包升级-android-apk-ios-跳商店-h5-提示刷新-设计文档" tabindex="-1">App 整包升级（Android APK / iOS 跳商店 / H5 提示刷新）设计文档 <a class="header-anchor" href="#app-整包升级-android-apk-ios-跳商店-h5-提示刷新-设计文档" aria-label="Permalink to &quot;App 整包升级（Android APK / iOS 跳商店 / H5 提示刷新）设计文档&quot;">​</a></h1><ul><li>日期：2026-09-16</li><li>状态：待实现</li><li>相关技能：<code>unibestX-skill</code>（1.3 运行时约束、4-utils 工具库、5-infra 基础设施）</li></ul><h2 id="_1-背景" tabindex="-1">1. 背景 <a class="header-anchor" href="#_1-背景" aria-label="Permalink to &quot;1. 背景&quot;">​</a></h2><p>uni-app x 的 app-Android 端编译为纯原生，<strong>没有 wgt 资源包、不支持热更新</strong>（DCloud 官方文档明确说明）。 因此 App 端唯一的版本迭代路径是<strong>整包升级</strong>：检测新版本 → 下载完整 APK → 唤起系统安装器。</p><h2 id="_2-目标与范围" tabindex="-1">2. 目标与范围 <a class="header-anchor" href="#_2-目标与范围" aria-label="Permalink to &quot;2. 目标与范围&quot;">​</a></h2><h3 id="_2-1-覆盖端" tabindex="-1">2.1 覆盖端 <a class="header-anchor" href="#_2-1-覆盖端" aria-label="Permalink to &quot;2.1 覆盖端&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">端</th><th style="text-align:left;">行为</th></tr></thead><tbody><tr><td style="text-align:left;">App-Android</td><td style="text-align:left;">完整流程：检测 → 下载（带进度）→ <code>uni.installApk</code> 安装</td></tr><tr><td style="text-align:left;">App-iOS</td><td style="text-align:left;">检测到新版本 → 跳转 AppStore（iOS 禁止程序化安装）</td></tr><tr><td style="text-align:left;">H5</td><td style="text-align:left;">比对构建 ID → 提示「发现新版本，点击刷新」</td></tr><tr><td style="text-align:left;">微信小程序</td><td style="text-align:left;"><strong>no-op</strong>，直接返回（小程序走微信自身的发版与静默更新机制）</td></tr></tbody></table><h3 id="_2-2-更新策略-四条全支持" tabindex="-1">2.2 更新策略（四条全支持） <a class="header-anchor" href="#_2-2-更新策略-四条全支持" aria-label="Permalink to &quot;2.2 更新策略（四条全支持）&quot;">​</a></h3><ol><li><strong>强制更新</strong> —— 后端下发 <code>forceUpdate: true</code>，弹窗不可关闭、返回键拦截，必须完成安装</li><li><strong>可选更新</strong> —— 用户可「稍后再说」，本次关闭，下次冷启动再提示</li><li><strong>跳过此版本</strong> —— 用户可「跳过此版本」，按 <code>versionCode</code> 持久化，永久静默直到出现更高版本</li><li><strong>静默下载</strong> —— 后台先下完 APK，再弹「下载完成，是否安装」</li></ol><h3 id="_2-3-明确不做-yagni" tabindex="-1">2.3 明确不做（YAGNI） <a class="header-anchor" href="#_2-3-明确不做-yagni" aria-label="Permalink to &quot;2.3 明确不做（YAGNI）&quot;">​</a></h3><ul><li>不做灰度 / 分渠道（后端若需要，由接口侧自行实现）</li><li>不做增量差分升级（uni-app x 无 wgt，差分包无意义）</li><li>不做 iOS 企业证书内部分发</li><li>不做下载断点续传（<code>uni.downloadFile</code> 不提供；失败即重试整包）</li><li>不改动现有 <code>src/http/request.uts</code> 拦截器逻辑</li></ul><h2 id="_3-文件清单" tabindex="-1">3. 文件清单 <a class="header-anchor" href="#_3-文件清单" aria-label="Permalink to &quot;3. 文件清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">文件</th><th style="text-align:left;">类型</th><th style="text-align:left;">职责</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/api/appVersion.uts</code></td><td style="text-align:left;">新增</td><td style="text-align:left;">版本查询接口（照 <code>src/api/foo.uts</code> 约定）</td></tr><tr><td style="text-align:left;"><code>src/utils/upgrade/index.uts</code></td><td style="text-align:left;">新增</td><td style="text-align:left;">升级编排层：比对、决策、下载、安装</td></tr><tr><td style="text-align:left;"><code>src/utils/upgrade/index.d.uts.ts</code></td><td style="text-align:left;">新增</td><td style="text-align:left;">IDE 声明（登记进 <code>HANDWRITTEN</code>）</td></tr><tr><td style="text-align:left;"><code>src/utils/upgrade/types.uts</code></td><td style="text-align:left;">新增</td><td style="text-align:left;">纯类型叶子</td></tr><tr><td style="text-align:left;"><code>src/components/AppUpdateDialog/AppUpdateDialog.uvue</code></td><td style="text-align:left;">新增</td><td style="text-align:left;">更新弹窗组件</td></tr><tr><td style="text-align:left;"><code>App.ku.uvue</code></td><td style="text-align:left;">修改</td><td style="text-align:left;">挂载弹窗组件</td></tr><tr><td style="text-align:left;"><code>src/pages/*/[basic|function|me|index|ai].uvue</code></td><td style="text-align:left;">修改</td><td style="text-align:left;"><code>onBackPress</code> 增加强制更新拦截</td></tr><tr><td style="text-align:left;"><code>src/pages/me/views/MeView.uvue</code></td><td style="text-align:left;">修改</td><td style="text-align:left;">「检查更新」手动入口</td></tr><tr><td style="text-align:left;"><code>src/i18n/locales/zh-CN.json</code> / <code>en-US.json</code></td><td style="text-align:left;">修改</td><td style="text-align:left;">新增 <code>upgrade</code> 文案段</td></tr><tr><td style="text-align:left;"><code>scripts/gen-uts-dts.mjs</code></td><td style="text-align:left;">修改</td><td style="text-align:left;"><code>HANDWRITTEN</code> 增加 <code>upgrade</code></td></tr><tr><td style="text-align:left;"><code>manifest.json</code></td><td style="text-align:left;">修改</td><td style="text-align:left;">声明 <code>REQUEST_INSTALL_PACKAGES</code> 权限</td></tr><tr><td style="text-align:left;"><code>vite.config.ts</code></td><td style="text-align:left;">修改</td><td style="text-align:left;">注入构建 ID（仅 H5 用）</td></tr></tbody></table><h3 id="_3-1-依赖关系" tabindex="-1">3.1 依赖关系 <a class="header-anchor" href="#_3-1-依赖关系" aria-label="Permalink to &quot;3.1 依赖关系&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MeView / App.uvue(冷启动)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>src/utils/upgrade/index.uts  ──► src/api/appVersion.uts ──► src/http/request.uts</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├──► src/utils/env/index.uts       (版本号读取)</span></span>
<span class="line"><span>        ├──► src/utils/i18n/index.uts      (全部文案)</span></span>
<span class="line"><span>        ├──► src/utils/toast/index.uts     (轻提示)</span></span>
<span class="line"><span>        └──► src/components/AppUpdateDialog (弹窗 UI)</span></span></code></pre></div><p><code>src/api/</code> 层只负责 HTTP，<code>src/utils/upgrade/</code> 只负责编排，UI 在组件层 —— 三层不互相越界。</p><h2 id="_4-接口契约" tabindex="-1">4. 接口契约 <a class="header-anchor" href="#_4-接口契约" aria-label="Permalink to &quot;4. 接口契约&quot;">​</a></h2><h3 id="_4-1-请求" tabindex="-1">4.1 请求 <a class="header-anchor" href="#_4-1-请求" aria-label="Permalink to &quot;4.1 请求&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {API_DOMAINS.DEFAULT}/app/version/latest?platform=android&amp;versionCode=100</span></span></code></pre></div><ul><li><code>platform</code>：<code>android</code> / <code>ios</code>（取自 <code>getCompilePlatform()</code>）</li><li><code>versionCode</code>：当前包的整型版本号</li><li><strong>必须携带 <code>extra: { ignoreAuth: true }</code></strong></li></ul><blockquote><p>⚠️ <strong><code>ignoreAuth: true</code> 是硬性要求，不是优化项。</strong><code>src/http/request.uts</code> 的响应拦截器对 401 会调用 <code>toLoginPage()</code>。 冷启动时用户未登录，一次升级检查请求就会把人<strong>踢到登录页</strong> —— 这类 bug 只在 「未登录 + 恰好有更新」的组合下出现，极难复现。</p></blockquote><h3 id="_4-2-响应" tabindex="-1">4.2 响应 <a class="header-anchor" href="#_4-2-响应" aria-label="Permalink to &quot;4.2 响应&quot;">​</a></h3><p>经 <code>HttpClient.request()</code> 已解包 <code>{ code, data }</code>，<code>.then()</code> 直接拿到 <code>data</code>：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export type IAppVersion = {</span></span>
<span class="line"><span>  versionName: string;   // &#39;1.2.0&#39;，仅用于展示</span></span>
<span class="line"><span>  versionCode: number;   // 120，比对以此为准</span></span>
<span class="line"><span>  downloadUrl: string;   // APK 直链 / iOS AppStore 链接</span></span>
<span class="line"><span>  forceUpdate: boolean;  // true 时走强制更新</span></span>
<span class="line"><span>  updateLog: string;     // 更新说明，多行用 \\n</span></span>
<span class="line"><span>  fileSize: number;      // 字节，用于展示与弱网提示</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="_4-3-接口函数" tabindex="-1">4.3 接口函数 <a class="header-anchor" href="#_4-3-接口函数" aria-label="Permalink to &quot;4.3 接口函数&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// src/api/appVersion.uts</span></span>
<span class="line"><span>export function getLatestAppVersion(platform: string, versionCode: number): Promise&lt;IAppVersion&gt;</span></span></code></pre></div><p>字段取值照 <code>foo.uts</code> 的 <code>getString</code> / <code>getNumber</code> 写法逐字段读取， 缺省值：字符串 <code>&#39;&#39;</code>、数字 <code>0</code>、布尔 <code>false</code>。任必填字段（<code>versionName</code> / <code>versionCode</code> / <code>downloadUrl</code>）为空时 reject。</p><h2 id="_5-版本比对" tabindex="-1">5. 版本比对 <a class="header-anchor" href="#_5-版本比对" aria-label="Permalink to &quot;5. 版本比对&quot;">​</a></h2><h3 id="_5-1-当前版本号来源" tabindex="-1">5.1 当前版本号来源 <a class="header-anchor" href="#_5-1-当前版本号来源" aria-label="Permalink to &quot;5.1 当前版本号来源&quot;">​</a></h3><p><strong>以 <code>versionCode</code> 为准，<code>versionName</code> 只用于展示。</strong></p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export function getCurrentVersionCode(): number   // uni.getAppBaseInfo().appVersionCode</span></span>
<span class="line"><span>export function getCurrentVersionName(): string   // uni.getAppBaseInfo().appVersion</span></span></code></pre></div><blockquote><p>⚠️ <strong>不要复用 <code>src/utils/env/index.uts</code> 的 <code>getAppVersion()</code> 做比对。</strong> 它的优先级是 <code>getSystemInfoSync().appVersion</code> → 小程序 <code>getAppBaseInfo()</code> → <code>VITE_APP_VERSION</code>， 三个来源会漂移，且返回的是 versionName 字符串，<strong>没有 versionCode</strong>。</p></blockquote><h3 id="_5-1-1-appversioncode-是字符串-不是数字" tabindex="-1">5.1.1 <code>appVersionCode</code> 是字符串，不是数字 <a class="header-anchor" href="#_5-1-1-appversioncode-是字符串-不是数字" aria-label="Permalink to &quot;5.1.1 \`appVersionCode\` 是字符串，不是数字&quot;">​</a></h3><p><code>@dcloudio/types</code> 中 <code>GetAppBaseInfoResult.appVersionCode</code> 的类型是 <strong><code>string</code></strong>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/** \`manifest.json\` 中应用版本名号 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">appVersionCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: string;</span></span></code></pre></div><p>因此 <code>getCurrentVersionCode(): number</code> 内部必须 <code>parseInt</code> 并处理解析失败：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const raw = \`\${uni.getAppBaseInfo().appVersionCode ?? &#39;&#39;}\`;</span></span>
<span class="line"><span>const code = parseInt(raw, 10);</span></span>
<span class="line"><span>return isNaN(code) ? 0 : code;</span></span></code></pre></div><p><code>0</code> 表示「读不到本地版本号」。此时 <code>serverCode &gt; 0</code> 恒成立，会导致<strong>每次都提示更新</strong>。 所以判定逻辑必须额外守卫：<code>localCode == 0</code> 时直接放弃本次检查并打日志，不弹窗。</p><h3 id="_5-1-2-这些-api-无法在仓库内验证" tabindex="-1">5.1.2 这些 API 无法在仓库内验证 <a class="header-anchor" href="#_5-1-2-这些-api-无法在仓库内验证" aria-label="Permalink to &quot;5.1.2 这些 API 无法在仓库内验证&quot;">​</a></h3><p><code>uni.installApk</code>、<code>uni.getAppBaseInfo().appVersionCode</code> 在 <code>node_modules</code> 里 <strong>都查不到 uni-app x 的权威类型定义</strong>（<code>@dcloudio/types</code> 提供的 <code>uni.d.ts</code> 是 <strong>legacy uni-app</strong> 的类型，tsconfig 通过 <code>types: [&quot;@dcloudio/types&quot;]</code> 引用它）。 uni-app x 的 API 由 HBuilderX 内置编译器校验，<strong>仓库内无法静态确认</strong>。</p><p>因此：<strong>字段名与签名一律以真机构建结果为准</strong>，IDE 没补全不代表写法错。 验证方式按 SKILL 红线 32 / 45 —— 必须走不带 <code>--compile</code> 的真机构建， 并先确认日志中 <code>编译为android class</code> 出现 ≥ 1 次。</p><h3 id="_5-2-判定规则" tabindex="-1">5.2 判定规则 <a class="header-anchor" href="#_5-2-判定规则" aria-label="Permalink to &quot;5.2 判定规则&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有更新  ⟺  serverVersionCode &gt; localVersionCode</span></span></code></pre></div><p>用严格大于，不用「不等于」—— 防止后端回滚版本导致客户端误判。</p><h2 id="_6-状态流转" tabindex="-1">6. 状态流转 <a class="header-anchor" href="#_6-状态流转" aria-label="Permalink to &quot;6. 状态流转&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>checkAppUpdate(manual: boolean)</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ├─ 微信小程序 ──────────────────────────────► return（no-op）</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ├─ H5 ────────────────────────────────────► 比对构建 ID，不一致则提示「点击刷新」</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> └─ App</span></span>
<span class="line"><span>     ├─ GET /app/version/latest</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ├─ 请求失败 ──────────────────────────► 静默；manual 时 toast 报错</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ├─ serverCode &lt;= localCode ───────────► 静默；manual 时 toast「已是最新版本」</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     └─ serverCode &gt; localCode</span></span>
<span class="line"><span>         ├─ !manual &amp;&amp; 已跳过该 versionCode ─► 静默</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ├─ forceUpdate ────────────────────► 强制弹窗</span></span>
<span class="line"><span>         │     · 无关闭按钮 / 点遮罩不关 / onBackPress 拦截</span></span>
<span class="line"><span>         │     · 不参与静默下载（用户不会干等）</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ├─ 静默下载已开启 ─────────────────► 后台 downloadFile（带进度）</span></span>
<span class="line"><span>         │     · 完成后弹「下载完成」[立即安装] [稍后]</span></span>
<span class="line"><span>         │     · 此分支不再走下面的可选弹窗</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         └─ 普通可选更新 ───────────────────► 弹窗（更新说明 + 包大小 + 版本号）</span></span>
<span class="line"><span>               ├─ [立即更新]   → 进度 → installApk</span></span>
<span class="line"><span>               ├─ [跳过此版本] → 持久化 versionCode，永久静默</span></span>
<span class="line"><span>               └─ [稍后再说]   → 只关闭，不持久化，下次冷启动再提示</span></span></code></pre></div><h3 id="_6-1-策略间优先级" tabindex="-1">6.1 策略间优先级 <a class="header-anchor" href="#_6-1-策略间优先级" aria-label="Permalink to &quot;6.1 策略间优先级&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forceUpdate  &gt;  静默下载  &gt;  跳过此版本  &gt;  普通可选</span></span></code></pre></div><ul><li><strong>强制更新压过静默下载</strong>：强制场景下用户必须立刻看到进度，静默反而增加等待焦虑</li><li><strong><code>manual = true</code> 压过「跳过此版本」与静默</strong>：用户主动点了「检查更新」，必须给出可见反馈</li></ul><h3 id="_6-2-持久化" tabindex="-1">6.2 持久化 <a class="header-anchor" href="#_6-2-持久化" aria-label="Permalink to &quot;6.2 持久化&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">值</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>upgradeSkippedVersionCode</code></td><td style="text-align:left;">number</td><td style="text-align:left;">被跳过的 <code>versionCode</code></td></tr></tbody></table><p>用 <code>uni.setStorageSync</code> / <code>uni.getStorageSync</code>（照 <code>src/store/vdom/token.uts</code> 的既有写法）。 「跳过此版本」比对的是 <code>versionCode</code> 而非 <code>versionName</code> —— 版本号字符串可能被后端复用，整型不会。</p><h2 id="_7-模块导出面" tabindex="-1">7. 模块导出面 <a class="header-anchor" href="#_7-模块导出面" aria-label="Permalink to &quot;7. 模块导出面&quot;">​</a></h2><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// src/utils/upgrade/types.uts</span></span>
<span class="line"><span>export type AppUpdateInfo = {</span></span>
<span class="line"><span>  versionName: string;</span></span>
<span class="line"><span>  versionCode: number;</span></span>
<span class="line"><span>  downloadUrl: string;</span></span>
<span class="line"><span>  forceUpdate: boolean;</span></span>
<span class="line"><span>  updateLog: string;</span></span>
<span class="line"><span>  fileSize: number;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// src/utils/upgrade/index.uts</span></span>
<span class="line"><span>export type UpdateState = &#39;idle&#39; | &#39;checking&#39; | &#39;available&#39; | &#39;downloading&#39; | &#39;ready&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const updateState: Ref&lt;UpdateState&gt;;        // 驱动弹窗</span></span>
<span class="line"><span>export const updateInfo: Ref&lt;AppUpdateInfo | null&gt;; // 当前待更新信息</span></span>
<span class="line"><span>export const downloadPercent: Ref&lt;number&gt;;          // 0-100</span></span>
<span class="line"><span>export const isForceUpdate: ComputedRef&lt;boolean&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export function checkAppUpdate(manual: boolean = false): void;</span></span>
<span class="line"><span>export function startDownloadAndInstall(): void;</span></span>
<span class="line"><span>export function skipCurrentVersion(): void;</span></span>
<span class="line"><span>export function dismissUpdate(): void;</span></span>
<span class="line"><span>export function isUpdateBlockingBack(): boolean;    // 供页面 onBackPress 判断</span></span>
<span class="line"><span>export function getCurrentVersionCode(): number;</span></span>
<span class="line"><span>export function getCurrentVersionName(): string;</span></span>
<span class="line"><span>export function clearSkippedVersion(): void;</span></span></code></pre></div><p><code>isUpdateBlockingBack()</code> 在 <strong>强制更新且弹窗可见</strong> 时返回 <code>true</code>，其余情况 <code>false</code>。</p><h2 id="_8-弹窗组件" tabindex="-1">8. 弹窗组件 <a class="header-anchor" href="#_8-弹窗组件" aria-label="Permalink to &quot;8. 弹窗组件&quot;">​</a></h2><h3 id="_8-1-挂载方式-组件挂全局骨架-方案-b" tabindex="-1">8.1 挂载方式：组件挂全局骨架（方案 B） <a class="header-anchor" href="#_8-1-挂载方式-组件挂全局骨架-方案-b" aria-label="Permalink to &quot;8.1 挂载方式：组件挂全局骨架（方案 B）&quot;">​</a></h3><p>组件 <code>src/components/AppUpdateDialog/AppUpdateDialog.uvue</code> 挂在 <code>App.ku.uvue</code> 根部， 在 <code>&lt;scroll-view&gt;</code> <strong>之后</strong>、<code>&lt;Tabbar&gt;</code> 同级，用绝对定位铺满遮罩。</p><p><strong>选它的理由</strong>：</p><ol><li>项目 <code>.env</code> 中 <code>VITE_TABBAR_MODE=4</code>（单页保活自定义 TabBar），遮罩天然盖得住 TabBar， 官方 <code>uni.openDialogPage</code> 的核心优势用不上</li><li>不动 <code>pages.config.json</code> → <code>pages.json</code> 的代码生成链路（<code>plugins/vite-plugin-uni-pages.ts</code> 会自动同步回写，插新页面进去有被覆盖风险）</li><li>全端同构，小程序 no-op 不需要额外分支</li></ol><p><strong>已知代价</strong>（见 8.3）：返回键拦截落到页面级 <code>onBackPress</code>，需要改 5 个页面文件。</p><blockquote><p>若将来切到 <code>VITE_TABBAR_MODE=1</code>（原生 TabBar），遮罩盖不住原生 TabBar 底部， 届时改用 <code>uni.openDialogPage</code> 即可 —— 模块导出面不变，只换 UI 挂载层。</p></blockquote><h3 id="_8-2-状态与交互" tabindex="-1">8.2 状态与交互 <a class="header-anchor" href="#_8-2-状态与交互" aria-label="Permalink to &quot;8.2 状态与交互&quot;">​</a></h3><p>组件直接订阅 <code>src/utils/upgrade/index.uts</code> 导出的 ref，<strong>不做 props 透传</strong>（避免 App.ku.uvue 多一层中转）。</p><table tabindex="0"><thead><tr><th style="text-align:left;">状态</th><th style="text-align:left;">弹窗表现</th></tr></thead><tbody><tr><td style="text-align:left;"><code>available</code> + 非强制</td><td style="text-align:left;">标题 + 版本号 + 包大小 + 更新说明 + [立即更新] [跳过此版本] [稍后再说]</td></tr><tr><td style="text-align:left;"><code>available</code> + 强制</td><td style="text-align:left;">同上但<strong>只有</strong> [立即更新]，无关闭按钮，遮罩不可点，返回键拦截</td></tr><tr><td style="text-align:left;"><code>downloading</code></td><td style="text-align:left;">进度条 + 百分比 + 已下载/总大小；强制模式不可取消</td></tr><tr><td style="text-align:left;"><code>ready</code></td><td style="text-align:left;">「下载完成」+ [立即安装] [稍后]（强制模式只有 [立即安装]）</td></tr><tr><td style="text-align:left;">其他</td><td style="text-align:left;">不渲染</td></tr></tbody></table><p><code>fileSize</code> 格式化为 <code>12.3 MB</code> 展示。更新说明按 <code>\\n</code> 拆分为多个兄弟 <code>&lt;text&gt;</code> 节点 （原生端 <code>&lt;text&gt;</code> 内不可嵌套多个文本节点，见 SKILL 红线 10）。</p><h3 id="_8-3-返回键拦截" tabindex="-1">8.3 返回键拦截 <a class="header-anchor" href="#_8-3-返回键拦截" aria-label="Permalink to &quot;8.3 返回键拦截&quot;">​</a></h3><p><code>onBackPress</code> 是<strong>页面级</strong>钩子（项目现有用法见 <code>src/pages/basic/basic.uvue:29</code>）， 组件内不可靠。因此需要在这 5 个页面的现有 <code>onBackPress</code> 回调<strong>开头</strong>加一行：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>onBackPress((options: OnBackPressOptions): boolean =&gt; {</span></span>
<span class="line"><span>  if (isUpdateBlockingBack()) {</span></span>
<span class="line"><span>    return true;   // 强制更新中，吞掉返回</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // ...原有逻辑不动</span></span>
<span class="line"><span>})</span></span></code></pre></div><p>页面清单：<code>src/pages/basic/basic.uvue</code>、<code>src/pages/function/function.uvue</code>、 <code>src/pages/me/me.uvue</code>、<code>src/pages/index/index.uvue</code>、<code>src/pages/ai/ai.uvue</code>。</p><h2 id="_9-下载与安装" tabindex="-1">9. 下载与安装 <a class="header-anchor" href="#_9-下载与安装" aria-label="Permalink to &quot;9. 下载与安装&quot;">​</a></h2><h3 id="_9-1-下载" tabindex="-1">9.1 下载 <a class="header-anchor" href="#_9-1-下载" aria-label="Permalink to &quot;9.1 下载&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let downloadTask: DownloadTask | null = null;</span></span>
<span class="line"><span>downloadTask = uni.downloadFile({</span></span>
<span class="line"><span>  url: info.downloadUrl,</span></span>
<span class="line"><span>  success: (res) =&gt; { /* res.tempFilePath → installApk */ },</span></span>
<span class="line"><span>  fail: (err) =&gt; { /* 读 err.errMsg，见 10.2 */ }</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>downloadTask.onProgressUpdate((res) =&gt; { downloadPercent.value = res.progress; });</span></span></code></pre></div><blockquote><p>⚠️ <strong>不能写成 <code>const downloadTask = uni.downloadFile(...)</code> 再在回调里引用它</strong> —— 局部声明在自身初始化表达式内不可见，Kotlin 编译报 <code>error18 找不到名称</code>。 必须 <code>let</code> 先声明、后赋值（SKILL 红线 31 / 1.1.14）。</p></blockquote><h3 id="_9-2-安装" tabindex="-1">9.2 安装 <a class="header-anchor" href="#_9-2-安装" aria-label="Permalink to &quot;9.2 安装&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uni.installApk({</span></span>
<span class="line"><span>  filePath: tempFilePath,   // ⚠️ 仅接受本地路径</span></span>
<span class="line"><span>  success: () =&gt; {},</span></span>
<span class="line"><span>  fail: (err) =&gt; { /* err.errCode -1300002 找不到文件 */ }</span></span>
<span class="line"><span>});</span></span></code></pre></div><ul><li><strong>平台</strong>：仅 Android（3.94+）。iOS / Web / 小程序均不支持</li><li><strong>路径</strong>：只接受本地路径，网络路径必须先 <code>uni.downloadFile</code> 落盘</li><li><strong>权限</strong>：Android 8.0+ 需 <code>android.permission.REQUEST_INSTALL_PACKAGES</code>（见 11.1）</li><li><strong>类型</strong>：<code>installApk</code> 在仓库 <code>node_modules</code> 中<strong>没有任何类型定义</strong>（uni-app x API 由 HBuilderX 内置编译器提供）。<strong>IDE 不给补全、不给报错，不代表写法有问题</strong> —— 唯一判据是真机构建结果（见 5.1.2）</li></ul><h3 id="_9-3-ios-分支" tabindex="-1">9.3 iOS 分支 <a class="header-anchor" href="#_9-3-ios-分支" aria-label="Permalink to &quot;9.3 iOS 分支&quot;">​</a></h3><p>iOS 不调 <code>installApk</code>，改为把用户送到 <code>downloadUrl</code>（AppStore 链接）。</p><p><strong>基线方案（默认实现）：<code>uni.showModal</code> 展示商店地址 + 复制。</strong></p><p>理由：仓库内<strong>查不到</strong> uni-app x 可用的打开外链 API —— 全盘搜索 <code>node_modules</code>， <code>openURL</code> 只出现在 <code>html5plus/plus.d.ts</code>，那是<strong>老版 uni-app 的 plus API，uni-app x 里不存在</strong>。 在无法静态确认的情况下，用 <code>showModal</code> 是唯一不依赖未验证 API 的写法。</p><p><strong>可选优化（真机验证通过后再升级）</strong>：若真机构建确认 <code>uni.openURL</code> 在 uni-app x 可用， 再把 iOS 分支换成直接跳转。这是一次<strong>纯局部替换</strong>，不影响模块其余部分。</p><h2 id="_10-错误处理" tabindex="-1">10. 错误处理 <a class="header-anchor" href="#_10-错误处理" aria-label="Permalink to &quot;10. 错误处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;">版本接口请求失败</td><td style="text-align:left;">静默；<code>manual</code> 时 <code>toastError</code></td></tr><tr><td style="text-align:left;">响应缺必填字段</td><td style="text-align:left;">reject → 同上</td></tr><tr><td style="text-align:left;">下载失败 / 网络中断</td><td style="text-align:left;">弹窗保留，提示「下载失败，请重试」，提供 [重试] 按钮</td></tr><tr><td style="text-align:left;">下载返回非 200</td><td style="text-align:left;">同「下载失败」</td></tr><tr><td style="text-align:left;"><code>installApk</code> fail</td><td style="text-align:left;"><code>toastError</code> + 兜底提示「请到应用市场更新」</td></tr><tr><td style="text-align:left;">存储读写失败</td><td style="text-align:left;">try/catch 吞掉，「跳过此版本」退化为仅本次生效</td></tr></tbody></table><h3 id="_10-1-失败值不是-error-实例" tabindex="-1">10.1 失败值不是 Error 实例 <a class="header-anchor" href="#_10-1-失败值不是-error-实例" aria-label="Permalink to &quot;10.1 失败值不是 Error 实例&quot;">​</a></h3><p>lime-request 会把拦截器抛出的 <code>Error</code> 转成 <code>LimeRequestFail</code> <strong>普通对象</strong>， <code>err.message</code> 取不到。必须读 <code>err.errMsg</code> 或 <code>err.cause.message</code>， 或照 <code>src/sub/httpDemo/httpDemo.uvue</code> 做 <code>instanceof Error</code> → <code>instanceof UTSJSONObject</code> 多级兜底。</p><h3 id="_10-2-日志" tabindex="-1">10.2 日志 <a class="header-anchor" href="#_10-2-日志" aria-label="Permalink to &quot;10.2 日志&quot;">​</a></h3><p>开发期用 <code>console.log</code> 输出关键节点（当前版本、服务端版本、判定结果、下载进度）， 与项目现有 <code>updateSystemInfo</code> 的日志风格一致。<strong>不引入日志库。</strong></p><h2 id="_11-平台缺口与前置条件" tabindex="-1">11. 平台缺口与前置条件 <a class="header-anchor" href="#_11-平台缺口与前置条件" aria-label="Permalink to &quot;11. 平台缺口与前置条件&quot;">​</a></h2><h3 id="_11-1-android-权限-阻塞项" tabindex="-1">11.1 Android 权限（阻塞项） <a class="header-anchor" href="#_11-1-android-权限-阻塞项" aria-label="Permalink to &quot;11.1 Android 权限（阻塞项）&quot;">​</a></h3><p><code>manifest.json</code> 的 <code>app-android</code> 段目前<strong>没有任何权限声明</strong>，需新增：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;app-android&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;distribute&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;&lt;uses-permission android:name=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">android.permission.REQUEST_INSTALL_PACKAGES</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>⚠️ 改权限后<strong>必须重新打自定义基座</strong>才能调试，标准基座不生效。 若暂时不便重打基座：代码照常实现，但 <code>installApk</code> 会失败 —— 需在验收时明确区分 「代码问题」与「基座未更新」。</p></blockquote><h3 id="_11-2-h5-构建-id-待实现细节" tabindex="-1">11.2 H5 构建 ID（待实现细节） <a class="header-anchor" href="#_11-2-h5-构建-id-待实现细节" aria-label="Permalink to &quot;11.2 H5 构建 ID（待实现细节）&quot;">​</a></h3><p><code>vite.config.ts</code> 用 <code>define</code> 注入构建时间戳，产物根生成 <code>version.json</code>， 运行时 fetch 比对，不一致则提示刷新。</p><blockquote><p>该分支需要改 <code>vite.config.ts</code> 并新增构建产物文件，<strong>作为独立小任务处理</strong>， 不阻塞 App 端主线。若判定成本过高，H5 可先降级为 no-op。</p></blockquote><h2 id="_12-测试策略" tabindex="-1">12. 测试策略 <a class="header-anchor" href="#_12-测试策略" aria-label="Permalink to &quot;12. 测试策略&quot;">​</a></h2><h3 id="_12-1-可测的部分-node-单测" tabindex="-1">12.1 可测的部分（node 单测） <a class="header-anchor" href="#_12-1-可测的部分-node-单测" aria-label="Permalink to &quot;12.1 可测的部分（node 单测）&quot;">​</a></h3><p>纯逻辑抽成无副作用函数，可脱离运行时测试：</p><ul><li><code>compareVersion(serverCode, localCode): boolean</code></li><li><code>shouldSkip(versionCode, manual): boolean</code></li><li><code>formatFileSize(bytes): string</code></li><li><code>decisionOf(info, localCode, manual, skippedCode): &#39;force&#39; | &#39;silent&#39; | &#39;optional&#39; | &#39;none&#39;</code></li></ul><p><strong>决策函数 <code>decisionOf</code> 是核心</strong>，四条策略的优先级全部收敛在它内部，必须有穷举用例覆盖 （force × manual × skipped 的 2×2×2 组合 + 无更新 + 网络失败）。</p><h3 id="_12-2-必须真机验证的部分" tabindex="-1">12.2 必须真机验证的部分 <a class="header-anchor" href="#_12-2-必须真机验证的部分" aria-label="Permalink to &quot;12.2 必须真机验证的部分&quot;">​</a></h3><p>按 SKILL 红线 32 / 45，<strong>不能用 <code>launch app-android --compile true</code> 冒充编译验证</strong>：</p><ul><li>强制更新时返回键确实被吞掉</li><li><code>installApk</code> 能唤起系统安装器（依赖 11.1 的权限与自定义基座）</li><li>进度条回调在真机上的频率与数值单调性</li></ul><h3 id="_12-3-测试文件位置" tabindex="-1">12.3 测试文件位置 <a class="header-anchor" href="#_12-3-测试文件位置" aria-label="Permalink to &quot;12.3 测试文件位置&quot;">​</a></h3><p>待 <code>writing-plans</code> 阶段确认项目是否已有 node 单测设施；若无，则最简方案是用 <code>node --test</code> 直接跑纯函数（这些函数不依赖 uni API，可独立成 <code>.ts</code> 便于测试）。</p><h2 id="_13-待确认假设" tabindex="-1">13. 待确认假设 <a class="header-anchor" href="#_13-待确认假设" aria-label="Permalink to &quot;13. 待确认假设&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">假设</th><th style="text-align:left;">若不成立的调整</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">后端接口为 <code>GET /app/version/latest</code>，字段照 <code>IAppVersion</code></td><td style="text-align:left;">只改 <code>src/api/appVersion.uts</code> 一处，其余不动</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">Android 权限可加入 <code>manifest.json</code> 并重打自定义基座</td><td style="text-align:left;">代码照常实现，验收时标注需补权限</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">H5 构建 ID 方案可行</td><td style="text-align:left;">H5 降级为 no-op</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">项目无现成 node 单测设施，用 <code>node --test</code></td><td style="text-align:left;">接入既有测试框架</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;"><code>uni.getAppBaseInfo().appVersionCode</code> 在 uni-app x 中字段名与 legacy 类型一致</td><td style="text-align:left;">真机构建报错时按编译器提示改名</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;"><code>uni.installApk</code> 在真机构建中可用（仓库无类型定义）</td><td style="text-align:left;">按编译器提示调整；仍不可用则退回「跳浏览器下载」</td></tr></tbody></table><h2 id="_14-实现顺序" tabindex="-1">14. 实现顺序 <a class="header-anchor" href="#_14-实现顺序" aria-label="Permalink to &quot;14. 实现顺序&quot;">​</a></h2><ol><li><code>src/api/appVersion.uts</code> + 类型（可独立验收）</li><li><code>src/utils/upgrade/</code> 纯逻辑 + 单测（<strong>先写测试</strong>）</li><li>模块接线：i18n 文案、toast、持久化</li><li><code>AppUpdateDialog.uvue</code> 组件</li><li>挂载到 <code>App.ku.uvue</code> + 5 个页面的 <code>onBackPress</code></li><li><code>MeView</code> 手动入口 + <code>App.uvue</code> 冷启动接入</li><li><code>HANDWRITTEN</code> 登记 + 跑 <code>node scripts/gen-uts-dts.mjs</code></li><li>Android 权限 + 真机验证</li></ol>`,110)])])}const h=a(o,[["render",l]]);export{u as __pageData,h as default};
